begin;
create table if not exists public.mme_ar_invoices(invoice_id uuid primary key default gen_random_uuid(),invoice_number text not null unique,customer_id uuid not null,invoice_date date not null,due_date date not null,currency char(3) not null default 'USD',subtotal numeric(16,2) not null check(subtotal>=0),tax_amount numeric(16,2) not null default 0 check(tax_amount>=0),total_amount numeric(16,2) generated always as (subtotal+tax_amount) stored,description text not null,source_module text not null default 'manual',source_reference text,invoice_status text not null default 'open' check(invoice_status in ('open','partially_paid','paid','void','written_off')),created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),unique(source_module,source_reference),check(due_date>=invoice_date));
create table if not exists public.mme_ar_payments(payment_id uuid primary key default gen_random_uuid(),payment_reference text not null unique,customer_id uuid not null,payment_date date not null,amount numeric(16,2) not null check(amount>0),currency char(3) not null default 'USD',payment_method text not null check(payment_method in ('cash','card','ach','check','store_credit','other')),external_reference text,status text not null default 'recorded' check(status in ('recorded','reversed')),recorded_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_ar_payment_allocations(allocation_id uuid primary key default gen_random_uuid(),payment_id uuid not null references public.mme_ar_payments(payment_id),invoice_id uuid not null references public.mme_ar_invoices(invoice_id),amount numeric(16,2) not null check(amount>0),created_at timestamptz not null default now(),unique(payment_id,invoice_id));
create table if not exists public.mme_ar_credit_memos(credit_memo_id uuid primary key default gen_random_uuid(),credit_memo_number text not null unique,customer_id uuid not null,invoice_id uuid references public.mme_ar_invoices(invoice_id),memo_date date not null,amount numeric(16,2) not null check(amount>0),reason text not null,status text not null default 'issued' check(status in ('issued','applied','void')),created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_ar_reminders(reminder_id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.mme_ar_invoices(invoice_id),reminder_type text not null check(reminder_type in ('upcoming','due','overdue','manual')),scheduled_at timestamptz not null,delivery_status text not null default 'queued' check(delivery_status in ('queued','sent','failed','cancelled')),created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_ar_audit_events(event_id uuid primary key default gen_random_uuid(),actor_auth_user_id uuid not null,action text not null,entity_type text not null,entity_id uuid,details jsonb not null default '{}',request_id uuid not null,created_at timestamptz not null default now());
create index if not exists mme_ar_invoice_customer_idx on public.mme_ar_invoices(customer_id,invoice_date desc);
create index if not exists mme_ar_invoice_due_idx on public.mme_ar_invoices(due_date,invoice_status);
create index if not exists mme_ar_payments_customer_idx on public.mme_ar_payments(customer_id,payment_date desc);
create index if not exists mme_ar_alloc_invoice_idx on public.mme_ar_payment_allocations(invoice_id);
create or replace function public.mme_ar_record_payment(p_reference text,p_customer_id uuid,p_date date,p_amount numeric,p_method text,p_external_reference text,p_actor uuid,p_allocations jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare v_payment uuid;v_alloc jsonb;v_invoice public.mme_ar_invoices%rowtype;v_total numeric(16,2):=0;v_allocated numeric(16,2):=0;v_amount numeric(16,2);v_customer uuid;v_currency char(3);begin if p_amount<=0 or p_customer_id is null or p_reference is null or trim(p_reference)='' then raise exception 'invalid_payment';end if;if jsonb_typeof(p_allocations)<>'array' then raise exception 'allocations_required';end if;select currency into v_currency from public.mme_ar_invoices where customer_id=p_customer_id and invoice_status in ('open','partially_paid') order by invoice_date limit 1;insert into public.mme_ar_payments(payment_reference,customer_id,payment_date,amount,payment_method,external_reference,recorded_by_auth_user_id) values(p_reference,p_customer_id,p_date,p_amount,p_method,p_external_reference,p_actor) returning payment_id into v_payment;for v_alloc in select * from jsonb_array_elements(p_allocations) loop v_amount:=(v_alloc->>'amount')::numeric;if v_amount<=0 then raise exception 'invalid_allocation_amount';end if;select * into v_invoice from public.mme_ar_invoices where invoice_id=(v_alloc->>'invoice_id')::uuid for update;if not found or v_invoice.customer_id<>p_customer_id or v_invoice.invoice_status in ('void','written_off') then raise exception 'invoice_not_allocatable';end if;if v_currency is not null and v_invoice.currency<>v_currency then raise exception 'currency_mismatch';end if;select coalesce(sum(amount),0) into v_total from public.mme_ar_payment_allocations where invoice_id=v_invoice.invoice_id;select coalesce(sum(amount),0) into v_allocated from public.mme_ar_credit_memos where invoice_id=v_invoice.invoice_id and status='applied';if v_total+v_allocated+v_amount>v_invoice.total_amount then raise exception 'allocation_exceeds_invoice_balance';end if;insert into public.mme_ar_payment_allocations(payment_id,invoice_id,amount) values(v_payment,v_invoice.invoice_id,v_amount);v_allocated:=v_total+v_allocated+v_amount;update public.mme_ar_invoices set invoice_status=case when v_allocated>=total_amount then 'paid' else 'partially_paid' end where invoice_id=v_invoice.invoice_id;end loop;if (select coalesce(sum(amount),0) from public.mme_ar_payment_allocations where payment_id=v_payment)>p_amount then raise exception 'allocation_exceeds_payment';end if;insert into public.mme_ar_audit_events(actor_auth_user_id,action,entity_type,entity_id,details,request_id) values(p_actor,'payment_recorded','payment',v_payment,jsonb_build_object('amount',p_amount,'reference',p_reference),gen_random_uuid());return v_payment;end $$;
create or replace function public.mme_ar_issue_credit_memo(p_number text,p_customer_id uuid,p_invoice_id uuid,p_date date,p_amount numeric,p_reason text,p_actor uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v public.mme_ar_invoices%rowtype;v_used numeric(16,2);v_id uuid;begin if p_amount<=0 or trim(coalesce(p_reason,''))='' then raise exception 'invalid_credit_memo';end if;select * into v from public.mme_ar_invoices where invoice_id=p_invoice_id for update;if not found or v.customer_id<>p_customer_id or v.invoice_status in ('void','written_off') then raise exception 'invoice_not_creditable';end if;select coalesce(sum(amount),0) into v_used from public.mme_ar_payment_allocations where invoice_id=p_invoice_id;select v_used+coalesce(sum(amount),0) into v_used from public.mme_ar_credit_memos where invoice_id=p_invoice_id and status<>'void';if v_used+p_amount>v.total_amount then raise exception 'credit_exceeds_invoice_balance';end if;insert into public.mme_ar_credit_memos(credit_memo_number,customer_id,invoice_id,memo_date,amount,reason,created_by_auth_user_id) values(p_number,p_customer_id,p_invoice_id,p_date,p_amount,p_reason,p_actor) returning credit_memo_id into v_id;insert into public.mme_ar_audit_events(actor_auth_user_id,action,entity_type,entity_id,details,request_id) values(p_actor,'credit_memo_issued','credit_memo',v_id,jsonb_build_object('invoice_id',p_invoice_id,'amount',p_amount),gen_random_uuid());return v_id;end $$;
create or replace view public.mme_ar_invoice_balances as select i.invoice_id,i.invoice_number,i.customer_id,i.invoice_date,i.due_date,i.currency,i.subtotal,i.tax_amount,i.total_amount,i.invoice_status,coalesce(p.paid,0)::numeric(16,2) as paid_amount,coalesce(c.credits,0)::numeric(16,2) as credit_amount,greatest(i.total_amount-coalesce(p.paid,0)-coalesce(c.credits,0),0)::numeric(16,2) as outstanding_amount,greatest(current_date-i.due_date,0) as days_past_due from public.mme_ar_invoices i left join (select invoice_id,sum(amount) paid from public.mme_ar_payment_allocations group by invoice_id)p on p.invoice_id=i.invoice_id left join (select invoice_id,sum(amount) credits from public.mme_ar_credit_memos where status='applied' group by invoice_id)c on c.invoice_id=i.invoice_id;
create or replace view public.mme_ar_aging_summary as select customer_id,currency,sum(outstanding_amount) filter(where due_date>=current_date)::numeric(16,2) as current_amount,sum(outstanding_amount) filter(where days_past_due between 1 and 30)::numeric(16,2) as days_1_30,sum(outstanding_amount) filter(where days_past_due between 31 and 60)::numeric(16,2) as days_31_60,sum(outstanding_amount) filter(where days_past_due between 61 and 90)::numeric(16,2) as days_61_90,sum(outstanding_amount) filter(where days_past_due>90)::numeric(16,2) as over_90,sum(outstanding_amount)::numeric(16,2) as total_outstanding from public.mme_ar_invoice_balances where outstanding_amount>0 and invoice_status not in ('void','written_off') group by customer_id,currency;
do $$ declare t text;begin foreach t in array array['mme_ar_invoices','mme_ar_payments','mme_ar_payment_allocations','mme_ar_credit_memos','mme_ar_reminders','mme_ar_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
revoke all on public.mme_ar_invoice_balances,public.mme_ar_aging_summary from public,anon,authenticated;grant select on public.mme_ar_invoice_balances,public.mme_ar_aging_summary to service_role;
revoke all on function public.mme_ar_record_payment(text,uuid,date,numeric,text,text,uuid,jsonb) from public,anon,authenticated;grant execute on function public.mme_ar_record_payment(text,uuid,date,numeric,text,text,uuid,jsonb) to service_role;
revoke all on function public.mme_ar_issue_credit_memo(text,uuid,uuid,date,numeric,text,uuid) from public,anon,authenticated;grant execute on function public.mme_ar_issue_credit_memo(text,uuid,uuid,date,numeric,text,uuid) to service_role;
commit;